{
  "skillId": "add-multiple-numbers-place-value",
  "atomType": "R",
  "theory": {
    "intro": "When adding or subtracting numbers with different numbers of digits, line them up by place value so each column holds ones, tens, hundreds and so on.",
    "facts": [
      "**Align the place values** (ones under ones, tens under tens) — line up the right-hand ends for whole numbers.",
      "Add a column at a time, **carrying** into the next column when it reaches $10$ or more.",
      "When adding three or more numbers, a column total can be larger than $19$ — carry the full tens part.",
      "Empty places act like a $0$."
    ],
    "steps": [
      "Write the numbers in a column, aligned by place value.",
      "Add (or subtract) the ones, then tens, then hundreds, carrying or borrowing as needed.",
      "Read off the answer."
    ]
  },
  "practice": {
    "foundation": [
      {
        "question_text": "Calculate $42000+5123+246$ by grouping digits with the same place value.",
        "structure": "add-three-unequal-lengths",
        "solution_text": "$42000+5123+246$\n$=42000+5000+(100+200)+(20+40)+(3+6)$\n$=47000+300+60+9$\n$=47369$"
      },
      {
        "question_text": "Calculate $735+64+8$ by aligning the place values.",
        "structure": "carry-full-tens-part",
        "solution_text": "$735+64+8$\n$=700+(30+60)+(5+4+8)$\n$=700+90+17$\n$=807$"
      },
      {
        "question_text": "Calculate $3806+475+29$ by grouping digits with the same place value.",
        "structure": "add-three-unequal-lengths",
        "solution_text": "$3806+475+29$\n$=3000+(800+400)+(70+20)+(6+5+9)$\n$=3000+1200+90+20$\n$=4310$"
      },
      {
        "question_text": "Calculate $8200+906+75+4$ by aligning the place values.",
        "structure": "add-four-unequal-lengths",
        "solution_text": "$8200+906+75+4$\n$=8000+(200+900)+(70)+(6+5+4)$\n$=8000+1100+70+15$\n$=9185$"
      },
      {
        "question_text": "Calculate $9480-326-57$.",
        "structure": "subtract-three-numbers",
        "solution_text": "$9480-326$\n$=9154$\n$9154-57$\n$=9097$"
      },
      {
        "question_text": "Calculate $7600+845-96$.",
        "structure": "mixed-add-then-subtract",
        "solution_text": "$7600+845$\n$=8445$\n$8445-96$\n$=8349$"
      }
    ],
    "development": [
      {
        "question_text": "Calculate $27840+3956+487+69$.",
        "structure": "add-four-unequal-lengths",
        "solution_text": "$27840+3956+487+69$\n$=31796+487+69$\n$=32283+69$\n$=32352$"
      },
      {
        "question_text": "Calculate $5687+2498+936+79$.\nTake care when a column total is greater than $19$.",
        "structure": "add-four-unequal-lengths",
        "solution_text": "$5687+2498+936+79$\n$=8185+936+79$\n$=9121+79$\n$=9200$"
      },
      {
        "question_text": "Calculate $12000-2865-438-79$.",
        "structure": "subtract-three-numbers",
        "solution_text": "$12000-2865$\n$=9135$\n$9135-438$\n$=8697$\n$8697-79$\n$=8618$"
      },
      {
        "question_text": "Calculate $6405+389+27-816$.",
        "structure": "mixed-add-then-subtract",
        "solution_text": "$6405+389+27$\n$=6794+27$\n$=6821$\n$6821-816$\n$=6005$"
      },
      {
        "question_text": "A student rewrites $42000+5123+246$ as $42000+51230+24600$.\nExplain the place-value error and calculate the original sum.",
        "structure": "align-unequal-lengths",
        "solution_text": "The student shifted the shorter numbers left instead of aligning their ones digits.\n$42000+5123+246$\n$=47369$"
      },
      {
        "question_text": "Three numbers have a total of $25000$.\nTwo of the numbers are $18450$ and $675$.\nFind the third number.",
        "structure": "missing-addend-among-three",
        "solution_text": "$25000-18450$\n$=6550$\n$6550-675$\n$=5875$"
      }
    ],
    "mastery": [
      {
        "question_text": "Calculate $6875+5489+3968$.\nShow how you handle a column total greater than $19$.",
        "structure": "carry-full-tens-part",
        "solution_text": "In the ones column, $5+9+8=22$, so write $2$ ones and carry $2$ tens.\n$6875+5489+3968$\n$=12364+3968$\n$=16332$"
      },
      {
        "question_text": "Find the missing number in $\\Box+4867+295=12000$.",
        "structure": "missing-addend-among-three",
        "solution_text": "$12000-4867$\n$=7133$\n$7133-295$\n$=6838$"
      },
      {
        "question_text": "Niko places $58$ in the hundreds and tens columns when adding $7240+583+58$, so it acts as $580$.\nExplain the error and find the correct total.",
        "structure": "align-unequal-lengths",
        "solution_text": "$58$ has $5$ tens and $8$ ones, so its ones digit must align with the other ones digits.\n$7240+583+58$\n$=7823+58$\n$=7881$"
      }
    ]
  }
}

